# First start on a PC that never had ClaudeScreen.
Verifier 'Claude-Work and System-Context created' ((Test-Path $Contexte) -and $Travail -like '*\Claude-Work')
Verifier 'instructions.md: template, no instruction' ((Test-Path $FichierInstructions) -and (Get-InstructionUtilisateur $FichierInstructions) -eq '' -and [IO.File]::ReadAllText($FichierInstructions) -match 'go to memory\.md')
Verifier 'guide copied' (Test-Path $FichierLisezMoi)
Verifier 'Persistent memory on by default: empty memory.md, nothing saved yet' ($menuMemoire.Checked -and $script:Memoire -and (Test-Path $FichierNotes) -and (Get-NoteMemoire $FichierNotes) -eq '' -and -not (Test-Path $FichierMemoire))
Verifier 'Terminal access off by default' (-not $menuTerminal.Checked -and -not $script:Terminal -and -not (Test-Path $FichierTerminal))
Verifier 'Contexts folder created' (Test-Path (Join-Path $DossierContextes 'Default.md'))
Verifier 'nothing sent to the bin' (@(Get-ChildItem $global:FauxBac).Count -eq 0)
$libelles = @($menu.Items | ForEach-Object { $_.Text })
Verifier 'menu items' (($libelles -join '|') -eq 'History|Model|Smooth mode|Persistent memory|Terminal access|Context: Default|Open the Claude-Work folder|Stop the current task||Quit') ($libelles -join '|')
